import json,time,os,boto3
from botocore.config import Config
DEPLOYMENT='one'
def handler(event,context):
    sqs=boto3.client("sqs",config=Config(connect_timeout=3,read_timeout=5,retries={"total_max_attempts":1}))
    result={"deployment":DEPLOYMENT,"function_version":context.function_version,"invoked_function_arn":context.invoked_function_arn,"request_id":context.aws_request_id,"event":event,"started_at":time.time()}
    sqs.send_message(QueueUrl=os.environ["MARKER_QUEUE"],MessageBody=json.dumps(result))
    if event.get("sleep"): time.sleep(min(event["sleep"],30))
    result["completed_at"]=time.time()
    return result

